UPDATE import_task SET status = #{status}, result_resource_id = #{resultResourceId},
    finished_at = CURRENT_TIMESTAMP(3), version = version + 1
WHERE id = #{id} AND version = #{version}

UPDATE import_task SET status = #{status}, error_code = #{errorCode}, error_message = #{errorMessage},
    finished_at = CURRENT_TIMESTAMP(3), version = version + 1
WHERE id = #{id} AND version = #{version}
